(ns seon.rules.seed
  "Bootstrap EDN fallback for starter `:seon.rule/*` rules when an ephemeral test store runs without `resources/seon/rules.edn` on disk."
  (:require [clojure.edn :as edn]))

(def starter-rules-edn
  "Canonical 43 starter :seon.rule/* rules for isolated/fresh stores (mirrors resources/seon/rules.edn)."
  "[#:seon.rule{:id :rule.seed/agent-scope, :doc \"Connect viewer agent to its :seon.agent/scope namespace entity.\", :category :seed, :stratum 10, :enabled? true, :target :any, :when [[?v :ctx/viewer ?aid] [?v :ctx/scope ?sc] [:db :code [?ns :seon.code.ns/name ?sc]]], :assert [[?v :rel/scope ?ns] [?ns :ctx/kind :seon.code.ns/entity] [?ns :ctx/source :walk] [?ns :seon.code.ns/name ?sc] [?ns :ctx/score 0.78] [?ns :ctx/why \"Agent namespace scope\"]]} #:seon.rule{:id :rule.seed/agent-task, :doc \"Connect viewer agent to its assigned :seon.task/* entity (resolved branch-first, then :main).\", :category :seed, :stratum 10, :enabled? true, :target :any, :when [[?v :ctx/viewer ?aid] [?v :ctx/task-id ?tid] [:db :task [?t :seon.task/id ?tid]] [:optional [:db :task [?t :seon.task/title ?title]]] [:optional [:db :task [?t :seon.task/plan ?plan]]] [:optional [:db :task [?t :seon.task/template? ?tpl]]]], :assert [[?v :rel/task ?t] [?t :ctx/kind :seon.task/entity] [?t :ctx/source :walk] [?t :seon.task/id ?tid] [?t :seon.task/title ?title] [?t :seon.task/plan ?plan] [?t :seon.task/template? ?tpl] [?t :ctx/score 1.0] [?t :ctx/why \"Assigned agent task\"]]} #:seon.rule{:id :rule.seed/child-agents, :doc \"Surface non-archived direct child agents via reverse :seon.agent/parent lookup.\", :category :seed, :stratum 10, :enabled? true, :target :any, :when [[?v :ctx/viewer ?aid] [?v :ctx/include-children? true] [:db :main [?c :seon.agent/parent ?aid]] [:db :main [?c :seon.agent/id ?cid]] [:not [:db :main [?c :seon.agent/archived? true]]]], :assert [[?v :rel/child-agent ?c] [?c :ctx/kind :seon.agent/entity] [?c :ctx/source :child] [?c :seon.agent/id ?cid] [?c :ctx/score 0.82] [?c :ctx/why \"Direct child sub-agent\"]]} #:seon.rule{:id :rule.seed/ctx-snapshot, :doc \"Always surface the viewer agent's own @ctx snapshot tile.\", :category :seed, :stratum 10, :enabled? true, :target :any, :when [[?v :ctx/viewer ?aid]], :assert [[:ctx/self :ctx/kind :seon.ctx/snapshot] [:ctx/self :ctx/source :ctx] [:ctx/self :ctx/score 1.0] [:ctx/self :ctx/why \"Agent @ctx runtime snapshot\"]]} #:seon.rule{:id :rule.seed/extra-namespaces, :doc \"Surface namespaces explicitly tuned via :seon.agent/context-prefs :extra-namespaces.\", :category :seed, :stratum 10, :enabled? true, :target :any, :when [[?v :ctx/extra-ns ?nsym] [:db :code [?ns :seon.code.ns/name ?nsym]]], :assert [[?v :rel/extra-ns ?ns] [?ns :ctx/kind :seon.code.ns/entity] [?ns :ctx/source :tuned] [?ns :seon.code.ns/name ?nsym] [?ns :ctx/score 0.88] [?ns :ctx/why \"Tuned extra namespace\"]]} #:seon.rule{:id :rule.seed/task-lineage, :doc \"Attach derived task DAG lineage (parents, subtasks, history, fixes) for the viewer.\", :category :seed, :stratum 10, :enabled? true, :target :any, :when [[?v :ctx/viewer ?aid] [?v :ctx/has-lineage? true]], :assert [[:ctx/lineage :ctx/kind :seon.task/lineage] [:ctx/lineage :ctx/source :walk] [:ctx/lineage :ctx/score 0.92] [:ctx/lineage :ctx/why \"Task DAG lineage & historical context\"]]} #:seon.rule{:id :rule.diag/collect-tree-discoveries, :doc \"Collect vars, namespaces, and schemas discovered/curated across child and subtask agents in the tree.\", :category :diagnosis, :stratum 20, :enabled? true, :target :any, :when [[?v :ctx/viewer ?aid] [?v :ctx/has-tree-peers? true] [:optional [?v :ctx/task-id ?tid]] [:not [?v :ctx/tree-collected? true]]], :assert [[?v :ctx/need-effect {:op :collect/tree-discoveries, :agent ?aid, :task ?tid}]]} #:seon.rule{:id :rule.diag/request-task-grounding, :doc \"Request boundary entity grounding over task title & custom plan (stripping template boilerplate).\", :category :diagnosis, :stratum 20, :enabled? true, :target :any, :when [[?v :rel/task ?t] [?t :seon.task/title ?title] [:not [?t :seon.task/template? true]] [:optional [?t :seon.task/plan ?plan]] [:not [?t :ctx/grounded? true]]], :assert [[?t :ctx/need-effect {:op :ground/task-text, :title ?title, :plan ?plan}]]} #:seon.rule{:id :rule.diag/underspecified-task, :doc \"Detect an underspecified task lacking tests, concrete ns/var mentions, and a detailed plan.\", :category :diagnosis, :stratum 21, :enabled? true, :target :any, :when [[?v :rel/task ?t] [?t :ctx/grounded? true] [?t :seon.task/title ?title] [:not [?t :seon.task/template? true]] [:not [:db :task [?t :seon.task/tests _]]] [:not [?t :rel/mentions-ns _]] [:not [?t :rel/mentions-var _]] [:optional [?t :ctx/custom-plan-len ?plen]] [:guard (or (nil? ?plen) (< ?plen 80))]], :assert [[?t :ctx/specificity :underspecified] [?t :ctx/why \"Underspecified task (missing tests & concrete symbols)\"]]} #:seon.rule{:id :rule.diag/search-on-underspecified, :doc \"Trigger boundary relevance search (lexical today, :vectors embedding ready) when task is underspecified.\", :category :diagnosis, :stratum 22, :enabled? true, :target :any, :when [[?t :ctx/specificity :underspecified] [?t :seon.task/title ?title] [:not [?t :ctx/searched? true]]], :assert [[?t :ctx/need-effect {:op :search/relevant, :query ?title, :k 6}]]} #:seon.rule{:id :rule.expand/schema-renderer, :doc \"When a task mentions a schema with :seon.schema/render (non-shim), surface its renderer function so the agent sees the exact entity data shape.\", :category :expand, :stratum 25, :enabled? true, :target :any, :when [[?t :rel/mentions-schema ?s] [:db :code [?s :seon.schema/render ?rfn]] [:guard (not (starts-with? (str ?rfn) \"seon.render.ui/\"))] [:db :code [?rv :seon.code.var/name ?rfn]]], :assert [[?s :rel/schema-renderer ?rv] [?rv :ctx/kind :seon.code.var/entity] [?rv :ctx/source :rule] [?rv :seon.code.var/name ?rfn] [?rv :ctx/score 0.86] [?rv :view/tag :tag/schema-renderer] [?rv :ctx/why \"Renderer for mentioned schema (shows entity data shape)\"]]} #:seon.rule{:id :rule.expand/scope-schema-consumer, :doc \"When a task mentions a schema, surface an in-scope function whose :seon.code.var/keywords already read or write attributes in that schema's namespace.\", :category :expand, :stratum 25, :enabled? true, :target :any, :when [[?v :ctx/viewer ?aid] [?v :ctx/scope ?sc] [?t :rel/mentions-schema ?s] [?s :seon.schema/key ?sk] [:db :code [?var :seon.code.var/ns ?sc]] [:db :code [?var :seon.code.var/keywords ?kw]] [:guard (= (namespace ?kw) (namespace ?sk))] [:db :code [?var :seon.code.var/name ?vsym]]], :assert [[?s :rel/scope-consumer ?var] [?var :ctx/kind :seon.code.var/entity] [?var :ctx/source :rule] [?var :seon.code.var/name ?vsym] [?var :ctx/score 0.87] [?var :view/tag :tag/schema-consumer] [?var :ctx/why \"In-scope function already reading/writing this schema\"]]} #:seon.rule{:id :rule.rank/curated-boost, :doc \"Give top relevance to entities explicitly curated via (user/curate! ...) on agent or task.\", :category :rank, :stratum 30, :enabled? true, :target :any, :when [[?e :rel/curated true]], :assert [[?e :ctx/score 0.98] [?e :ctx/source :curated] [?e :ctx/why \"Curated for task context\"]]} #:seon.rule{:id :rule.rank/mentioned-ns-boost, :doc \"Promote namespaces explicitly named in the task's title or custom plan.\", :category :rank, :stratum 30, :enabled? true, :target :any, :when [[?t :rel/mentions-ns ?ns]], :assert [[?ns :ctx/score 0.95] [?ns :ctx/source :rule] [?ns :ctx/why \"Explicitly named in task\"]]} #:seon.rule{:id :rule.rank/mentioned-schema-boost, :doc \"Promote Malli entity schemas whose domain matches the task (prevents attribute hallucination).\", :category :rank, :stratum 30, :enabled? true, :target :any, :when [[?t :rel/mentions-schema ?sc]], :assert [[?sc :ctx/score 0.9] [?sc :ctx/source :rule] [?sc :ctx/why \"Schema matched from task domain\"]]} #:seon.rule{:id :rule.rank/mentioned-var-boost, :doc \"Promote vars explicitly named in the task's title or custom plan.\", :category :rank, :stratum 30, :enabled? true, :target :any, :when [[?t :rel/mentions-var ?ve]], :assert [[?ve :ctx/score 0.96] [?ve :ctx/source :rule] [?ve :ctx/why \"Explicitly named in task\"]]} #:seon.rule{:id :rule.rank/tag-recent-entity, :doc \"Tag entities modified after initial store bootstrap and within the recent tx window.\", :category :rank, :stratum 30, :enabled? true, :target :any, :when [[:env :env/boot-tx ?boot] [:env :env/max-tx ?max-tx] [?e :ctx/modified-tx ?tx] [:guard (and (> ?tx ?boot) (>= ?tx (- ?max-tx 80)))]], :assert [[?e :ctx/recency :recent] [?e :ctx/why \"Modified recently\"]]} #:seon.rule{:id :rule.rank/tree-overlap-boost, :doc \"Compute multi-agent discovery overlap across the delegation tree; >= 2 agents strongly promotes entity.\", :category :rank, :stratum 30, :enabled? true, :target :any, :when [[?e :ctx/kind _] [:count ?n [?a :rel/tree-discovered ?e]] [:guard (>= ?n 2)]], :assert [[?e :ctx/tree-count ?n] [?e :ctx/score 0.94] [?e :ctx/source :tree] [?e :ctx/why (str \"Tree overlap across \" ?n \" agents\")]]} #:seon.rule{:id :rule.expand/covering-tests-for-hot-var, :doc \"Automatically surface covering deftest vars referencing any high-relevance target var.\", :category :expand, :stratum 32, :enabled? true, :target :any, :when [[?ve :ctx/kind :seon.code.var/entity] [?ve :seon.code.var/name ?sym] [?ve :ctx/score ?s] [:guard (>= ?s 0.94)] [:not [:db :code [?ve :seon.code.var/test? true]]] [:db :code [?te :seon.code.var/refs ?sym]] [:db :code [?te :seon.code.var/test? true]] [:db :code [?te :seon.code.var/name ?tsym]]], :assert [[?te :ctx/kind :seon.code.var/entity] [?te :seon.code.var/name ?tsym] [?te :ctx/source :rule] [?te :ctx/score 0.82] [?te :ctx/why (str \"Covering test for \" ?sym)]]} #:seon.rule{:id :rule.tags/tag-mentioned, :doc \"Tag namespaces and vars explicitly named in the task with :tag/mentioned.\", :category :rank, :stratum 35, :enabled? true, :target :any, :when [[?t :rel/mentions-ns ?ns]], :assert [[?ns :view/tag :tag/mentioned]]} #:seon.rule{:id :rule.tags/tag-modifiers, :doc \"Apply GTA-6 style composable modifier tags (:tag/mentioned, :tag/recent, :tag/tree-overlap, :tag/underspecified) onto matched entities.\", :category :rank, :stratum 35, :enabled? true, :target :any, :when [[?e :ctx/recency :recent]], :assert [[?e :view/tag :tag/recent]]} #:seon.rule{:id :rule.tags/tag-tree-overlap, :doc \"Tag any entity discovered by >= 2 agents in the delegation tree with :tag/tree-overlap.\", :category :rank, :stratum 35, :enabled? true, :target :any, :when [[?e :ctx/tree-count ?n] [:guard (>= ?n 2)]], :assert [[?e :view/tag :tag/tree-overlap]]} #:seon.rule{:id :rule.view/default-agent, :doc \"Default presentation for connected :seon.agent/entity (children or pinned).\", :category :present, :stratum 40, :enabled? true, :target :any, :when [[?e :ctx/kind :seon.agent/entity] [?e :ctx/score _]], :assert [[?e :view/fn seon.render.tiles/agent-tile] [?e :view/zone :static-prefix] [?e :view/layout :compact-card] [?e :view/priority 60]]} #:seon.rule{:id :rule.view/default-ctx, :doc \"Default presentation for the agent @ctx snapshot tile.\", :category :present, :stratum 40, :enabled? true, :target :any, :when [[?e :ctx/kind :seon.ctx/snapshot]], :assert [[?e :view/fn seon.render.tiles/ctx-tile] [?e :view/zone :static-prefix] [?e :view/layout :expanded-card] [?e :view/priority 100]]} #:seon.rule{:id :rule.view/default-doc, :doc \"Default presentation for :seon.code.doc/entity.\", :category :present, :stratum 40, :enabled? true, :target :any, :when [[?e :ctx/kind :seon.code.doc/entity] [?e :ctx/score _]], :assert [[?e :view/fn seon.render.tiles/doc-tile] [?e :view/zone :static-prefix] [?e :view/layout :compact-card] [?e :view/priority 70]]} #:seon.rule{:id :rule.view/default-health, :doc \"Default presentation for a pinned or discovered :seon.health/report.\", :category :present, :stratum 40, :enabled? true, :target :any, :when [[?e :ctx/kind :seon.health/report]], :assert [[?e :view/fn seon.render.tiles/health-panel] [?e :view/zone :static-prefix] [?e :view/layout :full-table] [?e :view/priority 94]]} #:seon.rule{:id :rule.view/default-lineage, :doc \"Default presentation for :seon.task/lineage.\", :category :present, :stratum 40, :enabled? true, :target :any, :when [[?e :ctx/kind :seon.task/lineage]], :assert [[?e :view/fn seon.render.lineage/task-lineage-tile] [?e :view/zone :static-prefix] [?e :view/layout :expanded-card] [?e :view/priority 90]]} #:seon.rule{:id :rule.view/default-ns, :doc \"Default presentation for any connected :seon.code.ns/entity.\", :category :present, :stratum 40, :enabled? true, :target :any, :when [[?e :ctx/kind :seon.code.ns/entity] [?e :ctx/score _]], :assert [[?e :view/fn seon.render.ns-tile/ns-tile] [?e :view/zone :static-prefix] [?e :view/layout :expanded-card] [?e :view/priority 76]]} #:seon.rule{:id :rule.view/default-rule, :doc \"Default presentation for pinned or evaluated :seon.rule/entity.\", :category :present, :stratum 40, :enabled? true, :target :any, :when [[?e :ctx/kind :seon.rule/entity] [?e :ctx/score _]], :assert [[?e :view/fn seon.render.tiles/rule-tile] [?e :view/zone :static-prefix] [?e :view/layout :compact-card] [?e :view/priority 65]]} #:seon.rule{:id :rule.view/default-schema, :doc \"Default presentation for any connected :seon.schema/entity.\", :category :present, :stratum 40, :enabled? true, :target :any, :when [[?e :ctx/kind :seon.schema/entity] [?e :ctx/score _]], :assert [[?e :view/fn seon.render.tiles/schema-tile] [?e :view/zone :static-prefix] [?e :view/layout :compact-card] [?e :view/priority 84] [?e :view.param/show-touching-vars? true]]} #:seon.rule{:id :rule.view/default-task, :doc \"Default presentation for :seon.task/entity.\", :category :present, :stratum 40, :enabled? true, :target :any, :when [[?e :ctx/kind :seon.task/entity] [?e :ctx/score _]], :assert [[?e :view/fn seon.render.tiles/task-tile] [?e :view/zone :static-prefix] [?e :view/layout :expanded-card] [?e :view/priority 92]]} #:seon.rule{:id :rule.view/default-var, :doc \"Default compact signature presentation for any connected :seon.code.var/entity.\", :category :present, :stratum 40, :enabled? true, :target :any, :when [[?e :ctx/kind :seon.code.var/entity] [?e :ctx/score _]], :assert [[?e :view/fn seon.render.tiles/var-tile] [?e :view/zone :static-prefix] [?e :view/layout :compact-row] [?e :view/priority 72] [?e :view.param/show-source? false]]} #:seon.rule{:id :rule.tree/nest-var-under-owning-ns, :doc \"When a var's owning namespace is also rendered in the same view, attach the var under its namespace via :view/parent.\", :category :layout, :stratum 46, :enabled? true, :target :html, :when [[?ve :ctx/kind :seon.code.var/entity] [?ve :view/fn _] [:db :code [?ve :seon.code.var/ns ?nsym]] [?ne :ctx/kind :seon.code.ns/entity] [?ne :seon.code.ns/name ?nsym] [?ne :view/fn _] [:not [?ve :view/parent _]]], :assert [[?ve :view/parent ?ne]]} #:seon.rule{:id :rule.tree/nest-covering-test-under-var, :doc \"Attach a covering test directly under its target var via :view/parent so graph self-organizes into a tree.\", :category :layout, :stratum 48, :enabled? true, :target :any, :when [[?ve :ctx/kind :seon.code.var/entity] [?ve :seon.code.var/name ?sym] [?ve :view/fn _] [:not [:db :code [?ve :seon.code.var/test? true]]] [?te :ctx/kind :seon.code.var/entity] [:db :code [?te :seon.code.var/test? true]] [:db :code [?te :seon.code.var/refs ?sym]]], :assert [[?te :view/parent ?ve] [?te :view/tag :tag/covering-test]]} #:seon.rule{:id :rule.layout/dedup-lineage-plan, :doc \"When the current task tile is already rendered, omit its duplicate plan inside task-lineage-tile.\", :category :layout, :stratum 50, :enabled? true, :target :any, :when [[?t :ctx/kind :seon.task/entity] [?t :view/fn _] [:ctx/lineage :view/fn _]], :assert [[:ctx/lineage :view.param/omit-current-plan? true]]} #:seon.rule{:id :rule.layout/demote-broad-scope-when-target-ns-mentioned, :doc \"Demote broad parent :scope ns to a 3-line summary strip when the task explicitly names specific target sub-namespaces.\", :category :layout, :stratum 50, :enabled? true, :target :any, :when [[?v :rel/scope ?sc-ns] [?v :rel/task ?t] [?t :rel/mentions-ns ?target-ns] [:guard (not= ?sc-ns ?target-ns)]], :assert [[?sc-ns :view/layout :summary-strip] [?sc-ns :view/priority 45] [?sc-ns :view.param/max-vars 0] [?sc-ns :ctx/why \"Demoted to summary strip (task names specific target ns)\"] [?target-ns :view/layout :expanded-card] [?target-ns :view/priority 95]]} #:seon.rule{:id :rule.layout/hide-templates-on-concrete-task, :doc \"Omit generic <task-templates> boilerplate on wire when the agent already has a concrete non-template task.\", :category :layout, :stratum 50, :enabled? true, :target :wire, :when [[?v :rel/task ?t] [:not [?t :seon.task/template? true]] [:ctx/lineage :view/fn _]], :assert [[:ctx/lineage :view.param/omit-templates? true]]} #:seon.rule{:id :rule.layout/expand-schema-renderer, :doc \"Expand schema renderer vars (stratum 52, overriding default-var compact-row) so entity field shapes are immediately visible.\", :category :layout, :stratum 52, :enabled? true, :target :any, :when [[?s :rel/schema-renderer ?rv]], :assert [[?rv :view/layout :expanded-card] [?rv :view.param/show-source? true] [?rv :view.param/show-callers? false] [?rv :view.param/source-limit 3800]]} #:seon.rule{:id :rule.layout/expand-scope-schema-consumer, :doc \"Expand in-scope schema consumer vars (stratum 52) so existing namespace query idioms are visible on Turn 0.\", :category :layout, :stratum 52, :enabled? true, :target :any, :when [[?s :rel/scope-consumer ?var]], :assert [[?var :view/layout :expanded-card] [?var :view.param/show-source? true] [?var :view.param/show-callers? false] [?var :view.param/source-limit 4500]]} #:seon.rule{:id :rule.layout/full-source-for-mentioned-var, :doc \"Expand source-limit to 12k chars for functions explicitly named in the task so edit targets never require an extra user/source turn.\", :category :layout, :stratum 52, :enabled? true, :target :any, :when [[?t :rel/mentions-var ?var]], :assert [[?var :view.param/source-limit 12000]]} #:seon.rule{:id :rule.layout/compact-health-in-html-rail, :doc \"Use a clean compact summary layout for System Health inside narrow HTML right-column rails (prevents horizontal clipping).\", :category :layout, :stratum 55, :enabled? true, :target :html, :when [[?e :ctx/kind :seon.health/report]], :assert [[?e :view/layout :compact-summary]]} #:seon.rule{:id :rule.layout/promote-recent-search-var, :doc \"Move recently modified high-relevance search hits to :ephemeral-tail with source+diff so KV prefix stays cached.\", :category :layout, :stratum 55, :enabled? true, :target :any, :when [[?e :ctx/kind :seon.code.var/entity] [?e :ctx.match/via :search] [?e :ctx.match/score ?s] [:guard (>= ?s 0.25)] [?e :ctx/recency :recent]], :assert [[?e :view/zone :ephemeral-tail] [?e :view/layout :expanded-card] [?e :view/priority 91] [?e :view.param/show-source? true] [?e :view.param/show-diff? true] [?e :view.param/badge \"recently modified\"]]} #:seon.rule{:id :rule.layout/promote-strong-var, :doc \"Expand full source & callers for explicitly mentioned, curated, or multi-agent tree-overlap vars.\", :category :layout, :stratum 55, :enabled? true, :target :any, :when [[?e :ctx/kind :seon.code.var/entity] [?e :ctx/score ?s] [:guard (>= ?s 0.94)]], :assert [[?e :view/layout :expanded-card] [?e :view/priority 93] [?e :view.param/show-source? true] [?e :view.param/show-callers? true]]}]")

(defn starter-rules
  "Parses the built-in starter rules EDN vector."
  {:malli/schema [:=> [:cat] [:vector :map]] :cost/ticks 5000000}
  []
  (let [v (edn/read-string starter-rules-edn)]
    (if (vector? v) v [])))
